define(['jquery', 'core/ajax'], function($, Ajax) {
    function renderTree(nodes) {
        const ul = $('<ul class="folder-tree"></ul>');

        nodes.forEach(node => {
            const li = $('<li></li>');
            const link = $('<a href="#"></a>')
                .text(node.name)
                .data('path', node.path)
                .on('click', function(e) {
                    e.preventDefault();
                    window.location.href =
                        M.cfg.wwwroot + '/local/shared_files/index.php?path=' + node.path;
                });

            li.append(link);

            if (node.children && node.children.length) {
                li.append(renderTree(node.children));
            }

            ul.append(li);
        });

        return ul;
    }

    function loadTree() {
        Ajax.call([{
            methodname: 'local_shared_files_get_tree',
            args: {}
        }])[0].done(function(tree) {
            $('#repo-folder-tree')
                .empty()
                .append(renderTree(tree));
        });
    }

    return {
        init: function() {
            loadTree();
        },
        reload: function() {   // 👈 important
            loadTree();
        }
    };
});
